import express from"express";import Product from"../models/productModel.js";const router=express.Router(),BASE_URL="https://www.bakaboom.es";router.get("/sitemap.xml",(async(req,res)=>{try{const products=await Product.find({slug:{$exists:!0,$ne:""},quantity:{$gt:0}}).select("slug categorySlug subcategorySlug subCategorySlug2 date updatedAt"),urls=new Map,addUrl=({loc:loc,lastmod:lastmod=new Date,changefreq:changefreq="weekly",priority:priority="0.5"})=>{urls.has(loc)||urls.set(loc,{loc:loc,lastmod:lastmod,changefreq:changefreq,priority:priority})};addUrl({loc:`${BASE_URL}/`,changefreq:"daily",priority:"1.0"}),addUrl({loc:`${BASE_URL}/about`,priority:"0.4"}),addUrl({loc:`${BASE_URL}/contacto`,priority:"0.5"}),addUrl({loc:`${BASE_URL}/privacy_policy`,priority:"0.3"}),addUrl({loc:`${BASE_URL}/delivery`,priority:"0.5"}),addUrl({loc:`${BASE_URL}/terms`,priority:"0.3"}),addUrl({loc:`${BASE_URL}/aviso-legal`,priority:"0.3"}),addUrl({loc:`${BASE_URL}/packs-bolsos-disenos-bakaboom`,priority:"0.7"}),addUrl({loc:`${BASE_URL}/personalizacion-bidones-termos`,priority:"0.7"}),addUrl({loc:`${BASE_URL}/personalizacion-jarras-vasos`,priority:"0.7"}),addUrl({loc:`${BASE_URL}/camisetas-diseno-bakaboom`,priority:"0.7"}),addUrl({loc:`${BASE_URL}/personalizacion-articulos`,priority:"0.7"}),addUrl({loc:`${BASE_URL}/personalizacion-de-tasas-en-paterna`,priority:"0.7"}),addUrl({loc:`${BASE_URL}/personalizacion-sudaderas-paterna`,priority:"0.7"}),addUrl({loc:`${BASE_URL}/personalizacion-camisetas-paterna`,priority:"0.7"}),products.forEach((product=>{const{slug:slug,categorySlug:categorySlug,subcategorySlug:subcategorySlug,subCategorySlug2:subCategorySlug2,date:date,updatedAt:updatedAt}=product,lastmod=updatedAt||date||new Date;categorySlug&&addUrl({loc:`${BASE_URL}/categoria/${categorySlug}`,lastmod:lastmod,changefreq:"weekly",priority:"0.8"}),categorySlug&&subcategorySlug&&addUrl({loc:`${BASE_URL}/categoria/${categorySlug}/${subcategorySlug}`,lastmod:lastmod,changefreq:"weekly",priority:"0.7"}),categorySlug&&subcategorySlug&&subCategorySlug2&&addUrl({loc:`${BASE_URL}/categoria/${categorySlug}/${subcategorySlug}/${subCategorySlug2}`,lastmod:lastmod,changefreq:"weekly",priority:"0.7"}),slug&&addUrl({loc:`${BASE_URL}/producto/${slug}`,lastmod:lastmod,changefreq:"weekly",priority:"0.6"})}));const xml=`<?xml version="1.0" encoding="UTF-8"?>\n<urlset\n  xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"\n>\n${Array.from(urls.values()).map((({loc:loc,lastmod:lastmod,changefreq:changefreq,priority:priority})=>`\n  <url>\n    <loc>${loc}</loc>\n    <lastmod>${new Date(lastmod).toISOString().split("T")[0]}</lastmod>\n    <changefreq>${changefreq}</changefreq>\n    <priority>${priority}</priority>\n  </url>`)).join("")}\n</urlset>`;res.header("Content-Type","application/xml").send(xml)}catch(error){console.error("Error generando sitemap:",error),res.status(500).send("Error generando sitemap")}}));export default router;